from itertools import combinations

def find_ruler(n=8, max_len=50):
    # x[0]=0, x[1]=2
    def backtrack(marks, used_dists):
        if len(marks) == n:
            return marks[:]
        last = marks[-1]
        for nxt in range(last+1, max_len+1):
            new_dists = set()
            ok = True
            for m in marks:
                d = nxt - m
                if d in used_dists or d in new_dists:
                    ok = False
                    break
                new_dists.add(d)
            if ok:
                marks.append(nxt)
                used_dists |= new_dists
                r = backtrack(marks, used_dists)
                if r: return r
                marks.pop()
                used_dists -= new_dists
        return None

    marks = [0, 2]
    used = {2}
    return backtrack(marks, used)

